2	// quote creates a policy that a later claim can be made against.
3	
4	import { type Customer, quote } from "./claim-office.js";
5	import { type Damage, policyCap, settleClaim } from "./claim-settlement.js";
6	import { type Item } from "./item-catalogue.js";
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface ClaimStep {
14	  op: "claim";
15	  policy: number;
16	  incident: { cause: string; damages: Damage[] };
17	}
18	
19	export type Step = QuoteStep | ClaimStep;
20	
21	export interface Scenario {
22	  customer: Customer;
23	  steps: Step[];
24	}
25	
26	export interface QuoteResult {
27	  premium: number;
28	}
29	
30	export interface ClaimResult {
31	  payout: number;
32	  remainingCap: number;
33	}
