35	export type StepResult = QuoteResult | ClaimResult;
36	
37	// A policy, once quoted, carries its items and whatever cap it has left.
38	interface Policy {
39	  items: Item[];
40	  remainingCap: number;
41	}
42	
43	export function runScenario(scenario: Scenario): StepResult[] {
44	  const policies = new Map<number, Policy>();
45	  let contractsSoFar = 0;
46	
47	  return scenario.steps.map((step, index) => {
48	    if (step.op === "quote") {
49	      const premium = quote(scenario.customer, step.items, contractsSoFar);
50	      contractsSoFar += 1;
51	      policies.set(index, {
52	        items: step.items,
53	        remainingCap: policyCap(step.items),
54	      });
55	      return { premium };
56	    }
57	
58	    const policy = policies.get(step.policy) as Policy;
59	    const settlement = settleClaim(
60	      policy.items,
61	      step.incident.damages,
62	      policy.remainingCap,
63	    );
64	    policy.remainingCap = settlement.remainingCap;
65	    return settlement;
66	  });
67	}
