2	// The claim-office command: reads a scenario as JSON on stdin and writes the
3	// corresponding results as JSON on stdout. Transport only -- every decision
4	// belongs to the domain modules it calls.
5	
6	import { type Scenario, runScenario } from "./scenario.js";
7	
8	async function readStdin(): Promise<string> {
9	  const chunks: Buffer[] = [];
10	  for await (const chunk of process.stdin) {
11	    chunks.push(Buffer.from(chunk));
12	  }
13	  return Buffer.concat(chunks).toString("utf8");
14	}
15	
16	async function main(): Promise<void> {
17	  const scenario = JSON.parse(await readStdin()) as Scenario;
18	  const results = runScenario(scenario);
19	  process.stdout.write(`${JSON.stringify({ results })}\n`);
20	}
21	
22	await main();
