1	// How the MHPCO settles a claim against a policy: what the policy covers in
2	// total, and what it will pay out. This is settlement policy, separate from
3	// the premium policy that decides what the office charges.
4	
5	import { type Item, insuranceValue } from "./item-catalogue.js";
6	
7	const CAP_MULTIPLE = 2;
8	const DEDUCTIBLE = 100;
9	const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
10	const REDUCED_REIMBURSEMENT_RATE = 0.5;
11	
12	// The insurance sum is the sum of the insured items' insurance values; the
13	// block discount affects the premium only, never the insurance sum.
14	export function insuranceSum(items: Item[]): number {
15	  return items.reduce((total, item) => total + insuranceValue(item), 0);
16	}
17	
18	// The total payout per policy is capped at twice the insurance sum.
19	export function policyCap(items: Item[]): number {
20	  return insuranceSum(items) * CAP_MULTIPLE;
21	}
22	
23	export interface Damage {
24	  itemType: string;
25	  amount: number;
26	}
27	
28	export interface Settlement {
29	  payout: number;
30	  remainingCap: number;
31	}
32	
33	// Damage to an item enchanted at this level or above is reimbursed at half.
34	function isReducedReimbursement(item: Item): boolean {
35	  return (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT;
36	}
37	
38	// The reimbursement clauses decide what a damage is worth before the
39	// deductible is withheld. Dragon material is fully reimbursed, which is also
40	// the default for an item no clause reduces, so it needs no separate branch:
41	// where dragon material meets high enchantment the spec's examples give the
42	// 50 % rule precedence (dragon sword, enchantment 8 or 9, damage 1000 G ->
43	// payout 400 G).
44	function reimbursableAmount(item: Item, damage: Damage): number {
45	  return isReducedReimbursement(item)
46	    ? damage.amount * REDUCED_REIMBURSEMENT_RATE
47	    : damage.amount;
48	}
49	
50	// A deductible is withheld per damage event, after the reimbursement clauses
51	// have decided what the damage is worth.
52	function damagePayout(item: Item, damage: Damage): number {
53	  return reimbursableAmount(item, damage) - DEDUCTIBLE;
54	}
55	
56	// Which covered item a reported damage refers to. A damage report names only
57	// an item type, so the office has to match it against what the policy actually
58	// covers. A damage naming a type the policy does not cover is a rejected claim,
59	// not a settled one; until that rejection rule exists, this assumes the caller
60	// has only passed damages the policy covers.
61	function coveredItemFor(items: Item[], damage: Damage): Item {
62	  return items.find((item) => item.type === damage.itemType) as Item;
63	}
64	
65	// Every damage in an incident is settled on its own -- two damaged swords are
66	// two damage events, each bearing its own deductible -- and the claim pays out
67	// the sum of them.
68	function claimPayout(items: Item[], damages: Damage[]): number {
69	  return damages.reduce(
70	    (total, damage) =>
71	      total + damagePayout(coveredItemFor(items, damage), damage),
72	    0,
73	  );
74	}
75	
76	// The total payout per policy is capped, so the office never pays more than
77	// the cap the policy has left: a claim that wants more is reduced to it.
78	function payoutWithinRemainingCap(
79	  desiredPayout: number,
80	  remainingCap: number,
81	): number {
82	  return Math.min(desiredPayout, remainingCap);
83	}
84	
85	// Amounts are rounded to whole G in the MHPCO's favour: a payout is rounded
86	// down. Intermediate amounts are kept as fractions.
87	function roundPayoutInMhpcoFavor(payout: number): number {
88	  return Math.floor(payout);
89	}
90	
91	// Settling a claim: what the incident is worth, reduced to what the policy's
92	// cap still permits, and what that leaves of the cap for later claims.
93	export function settleClaim(
94	  items: Item[],
95	  damages: Damage[],
96	  remainingCap: number,
97	): Settlement {
98	  const desiredPayout = claimPayout(items, damages);
99	  const permittedPayout = payoutWithinRemainingCap(desiredPayout, remainingCap);
100	  const payout = roundPayoutInMhpcoFavor(permittedPayout);
101	  return { payout, remainingCap: remainingCap - payout };
102	}
